styleBlocks.css:
.import-preview-modal {
  width: min(94vw, 920px);
  max-width: 920px;
  max-height: 90vh;
  padding: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
}

.import-review-summary {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(150px, .7fr);
  gap: 10px 14px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 70%, transparent);
}

.import-review-file {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.import-review-label {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.import-review-file strong {
  min-width: 0;
  color: var(--text-primary);
  font-size: 13px;
  overflow-wrap: anywhere;
}

.import-review-stats {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.import-review-stat {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 24px;
  padding: 3px 9px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 12px;
}

.import-review-warning {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--yellow);
  border-radius: var(--radius-sm);
  background: var(--yellow-bg);
  color: var(--yellow);
  font-size: 13px;
  line-height: 1.5;
}

.import-review-date-warning {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.import-review-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, 260px) auto;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
}

.import-filter-group {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
}

.import-filter-btn {
  min-height: 32px;
  padding: 5px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 76%, transparent);
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.import-filter-btn.active {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  background: color-mix(in srgb, var(--accent) 16%, var(--bg-card));
  color: var(--text-primary);
}

.import-review-search,
.import-map-input,
.import-value-input,
.import-unit-input {
  width: 100%;
  min-width: 0;
  min-height: 34px;
  padding: 6px 9px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-family: var(--font-mono);
  font-size: 12px;
}

.import-unit-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  cursor: pointer;
  text-align: left;
  line-height: 1.25;
  white-space: normal;
}

.import-unit-combo {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  gap: 5px;
  width: 100%;
  min-width: 0;
}

.import-unit-picker-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 34px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  cursor: pointer;
  font: inherit;
}

.import-visible-count {
  justify-self: end;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 11px;
  white-space: nowrap;
}

.import-table-wrap {
  margin-top: 16px;
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 62%, transparent);
  -webkit-overflow-scrolling: touch;
}

.import-range-option {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 68%, transparent);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 13px;
  line-height: 1.4;
}

.import-range-option input {
  flex: 0 0 auto;
  width: 18px;
  height: 18px;
  margin-top: 1px;
  accent-color: var(--accent);
}

.import-range-option span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.import-review-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 24px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 96%, var(--bg-card));
}

.import-table th {
  background: var(--bg-card); padding: 8px 12px; text-align: left;
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-muted);
}

.import-status-dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 16%, transparent);
  vertical-align: middle;
}

.import-exclude-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  min-width: 34px;
  min-height: 34px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-muted);
  cursor: pointer;
  font: inherit;
  font-size: 20px;
  font-weight: 700;
  padding: 0;
  line-height: 1;
  opacity: 0.9;
}

.import-exclude-btn.is-restore {
  color: var(--green);
  border-color: color-mix(in srgb, var(--green) 45%, var(--border));
  background: color-mix(in srgb, var(--green) 10%, var(--bg-secondary));
}

.import-unit-menu {
  position: fixed;
  z-index: 3000;
  overflow: auto;
  padding: 6px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
  -webkit-overflow-scrolling: touch;
}

.import-unit-menu.is-mobile {
  left: 12px;
  right: 12px;
  bottom: calc(12px + env(safe-area-inset-bottom));
  width: auto;
  max-width: none;
  max-height: min(60dvh, 360px);
}

.import-unit-option {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 38px;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
  font: inherit;
  font-family: var(--font-mono);
  font-size: 13px;
  text-align: left;
  white-space: normal;
  overflow-wrap: anywhere;
}

.import-unit-option[aria-selected="true"] {
  background: color-mix(in srgb, var(--accent) 18%, var(--bg-card));
  color: var(--text-primary);
  font-weight: 800;
}

.import-map-control {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
}

.import-map-picker-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  min-width: 36px;
  min-height: 36px;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--border));
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  cursor: pointer;
  font: inherit;
}

.import-map-picker-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  color: var(--accent);
}

.import-map-picker-icon svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.import-map-picker-btn:hover,
.import-map-picker-btn:focus {
  border-color: var(--accent);
  color: var(--text-primary);
  background: color-mix(in srgb, var(--accent) 12%, var(--bg-card));
  outline: none;
}

.import-suggested-key {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.import-mapped-key {
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.import-suggested-key code {
  display: block;
  margin-top: 2px;
  color: var(--text-primary);
  font-family: var(--font-mono);
}

.import-mapped-key code {
  display: block;
  margin-top: 2px;
  color: var(--text-primary);
  font-family: var(--font-mono);
}

.import-preview-modal,
  #import-modal.import-preview-modal,
  .modal.import-preview-modal {
    width: calc(100vw - 12px);
    height: calc(100vh - 12px);
    height: calc(100dvh - 12px);
    max-height: none;
    padding: 0;
  }

.import-table,
  .import-table tbody,
  .import-table tr,
  .import-table td {
    display: block;
    width: 100%;
    box-sizing: border-box;
  }

.import-table tr {
    position: relative;
    margin-bottom: 9px;
    padding: 13px 11px 11px;
    border: 1px solid var(--border);
    border-left-width: 4px;
    border-radius: var(--radius-sm);
    background: color-mix(in srgb, var(--bg-card) 72%, transparent);
  }

.import-table td {
    display: grid;
    grid-template-columns: minmax(74px, 28%) minmax(0, 1fr);
    align-items: start;
    gap: 8px;
    padding: 5px 0;
    border-bottom: 0;
    white-space: normal;
  }

.import-table td::before {
    content: attr(data-label);
    color: var(--text-muted);
    font-family: var(--font-mono);
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    line-height: 1.35;
  }

.import-table .import-name-cell {
    display: block;
    min-height: 38px;
    padding-top: 0;
    color: var(--text-primary);
    font-size: 14px;
    font-weight: 800;
    line-height: 1.3;
  }

.import-table td.import-row-action-btn {
    position: absolute;
    top: 10px;
    right: 10px;
    display: block;
    width: auto;
    padding: 0;
  }

.import-review-actions {
    position: sticky;
    bottom: 0;
    z-index: 3;
    padding: 12px;
    flex-wrap: wrap;
    box-shadow: 0 -8px 18px color-mix(in srgb, var(--bg-primary) 14%, transparent);
  }

.rec-next-card {
  border: 1px solid var(--border); border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-secondary) 55%, transparent);
  padding: 12px; display: grid; gap: 8px;
}

.rec-next-source {
  font-family: var(--font-mono); font-size: 10px; font-weight: 800;
  color: var(--accent); text-transform: uppercase;
}

.rec-next-primary {
  color: var(--green); font-size: 13px; padding: 8px 10px;
  background: color-mix(in srgb, var(--green) 8%, transparent);
  border-radius: var(--radius-sm);
}

.rec-next-primary-label {
  display: block; margin-bottom: 2px; color: var(--text-muted);
  font-family: var(--font-mono); font-size: 9px; font-weight: 700;
  letter-spacing: 0.04em; text-transform: uppercase;
}

.db-genome-empty,
.db-correlation-empty {
  width: 100%; min-height: 130px; padding: 18px; border-radius: var(--radius-sm);
  border: 1px dashed var(--border); background: transparent; color: var(--text-primary);
  display: flex; flex-direction: column; align-items: flex-start; justify-content: center;
  gap: 6px; text-align: left; font: inherit;
}

#import-manual-date,
#import-sample-time,
#import-fasting {
  min-height: 34px;
  padding: 5px 9px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font: inherit;
  font-family: var(--font-mono);
}

.batch-progress-counter {
  text-align: center; color: var(--accent); font-weight: 600; font-size: 14px;
  margin-bottom: 12px;
}
